from pathlib import Path
import re,json
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[3];ONT=ROOT/'.g5/ontology'
rows=[
('concepts/transactions-and-dev-mode.g5.md','dev-mode.overwrite-guard.dependency-policy','dev-mode.overwrite-guard','Q-24','May a parent replace a dependency that is already in developer mode?','Source guard checks only the top-level Install parameter; native N-R05-DEVUP replaces the dependency at another version and clears developer mode. Same-version DEVSAME skips it.','Preserve the stated install overwrite guard for dependencies; load scope follows the parent force/load question.','Allow top-level guard only, with a warning when dependency developer mode is cleared.','install refusal, dependency replacement and developer working copy preservation'),
('concepts/transactions-and-dev-mode.g5.md','transaction.flag-sources.dependency-closure','transaction.flag-sources.dependency-defaults','Q-25','May an escaped NoJournal dependency remain without its own dependencies?','N-R05-NESTF leaves d1 installed and rolls d2 back because the flat closure loads d2 under parent parameters before d1.','Require closure consistency as intent; record the observed violating state rather than assuming a repair.','Document temporary inconsistency after failure, or use one load-wide transaction mode.','dependency satisfaction, mixed-mode rollback and retry'),
('features/history.g5.md','history.committed.escaped-dependency','history.committed','Q-26','Should a parent record count writes kept only by its NoJournal dependency?','The property says any action changes kept. N-R05-M5 leaves child data while top-level marker can remain false and the child row can be lost.','Count surviving child writes in the parent outcome; retain the distinction between parent and child records.','Keep per-activation marker only and rely on independent child records after a repair.','Committed truth, record existence and aggregate load outcome'),
('features/history.g5.md','history.delete.global-errors','history.delete','Q-27','Must global delete report namespace errors other than missing permission?','DeleteHistoryGlobally catches all exceptions; a native unknown-column comparison distinguishes local failure from global success.','Report errors that mean requested deletion was not performed.','Keep best-effort behavior and explicitly list skipped namespaces and errors.','global delete status and namespace scope'),
('features/history.g5.md','history.read.global-shape','history.read.api','Q-28','Must programmatic global history rows carry their namespace and ID?','CLI output carries namespace; GlobalRecords ROWSPEC omits namespace and ID, and native H10 repeats caller rows.','Return identities sufficient for a caller to distinguish colliding namespace-local IDs.','Keep the legacy row shape and document a separate namespace-aware API.','global query scope, identity and details lookup'),
('features/history.g5.md','history.retention.running-policy','history.retention','Q-29','May automatic retention remove an action that has not ended?','The as-built quoted cutoff deletes nothing. With that defect repaired the filter uses TimeStart only; the Python reader model can then remove active rows.','Retain the documented age rule while keeping deletion/finalization races explicit; no repair outcome is claimed.','Skip active rows and define how killed actions eventually expire.','retention fix, active writers and abnormal process ends'),
('features/history.g5.md','history.survives-rollback.repair-policy','history.survives-rollback','Q-30','Which repair should preserve child history without lying about Committed?','Naive durable rows can mark rolled-back writes committed. The inherited bounded variants distinguish guarded close, before-image ordering, per-activation NoJournal and SIGKILL residuals; mirroring is untested.','Keep current survival requirement and report the repair as undecided; no product repair applied.','Use one load-wide mode plus guarded close and mark ordering, or extend the repair to durably mark escaped child writes.','D1 and aliases, caller rollback, crash cuts and mirrored history'),
('features/history.g5.md','history.committed.marking.refusal-policy','history.committed.marking','Q-31','Should the no-transaction marker run only after every refusal?','LoadNewModule marks before manifest validation; a later refusal can keep no data yet read Committed=1 (G:D12). The property says noncommitted means nothing kept or rolled back.','Keep the intent that a no-write refusal is uncommitted; classify the early marker as a defect.','Declare every no-transaction attempt committed from its start and change the owning I rule explicitly.','validation timing, no-transaction history, D12 and requirement refusals')]
for file,id,parent,alias,q,evidence,assumption,alternative,affected in rows:
 p=ONT/file;s=p.read_text()
 if '[Q · '+id+']' in s:continue
 block=f'<a id="{id}"></a>\n[Q · {id}]\n\n{q}\n\n- Evidence: {evidence}\n- Working assumption: {assumption}\n- Alternative: {alternative}\n- Affected claims: {affected}. Alias {alias}.\n\n'
 s=s.replace('## Metadata',block+'## Metadata',1)
 # Place a child link beside the actual owning parent statement, not solely in a register.
 pat=r'(^\[[IDQ] · '+re.escape(parent)+r'\]\n)(.*?)(?=\n<a id=|\n## |\Z)';m=re.search(pat,s,re.M|re.S);assert m,parent
 body=m[2].rstrip()+f'\n\nUnresolved {alias}: [{q}](#{id})\n'
 s=s[:m.start(2)]+body+s[m.end(2):]
 s+=f'\n### {id}\n\n- agent-provided\n- user-facing-behavior\n- Expands: [{parent}](#{parent}).\n\nSources: inherited `.g5/Verus_verification/open_questions.md` {alias}, source/native cases named in the block; [extension evidence](../../uplift/consolidated/extension/REPORT.md).\n';p.write_text(s)
(HERE/'inherited-question-aliases.json').write_text(json.dumps([{'alias':r[3],'ontology':r[1],'path':r[0]} for r in rows],indent=2));print(len(rows),'inherited questions given canonical child owners')
